window.KH_SURA(65, {"sura": "الطلاق", "n": 65, "ayat": {"1": "يَاأَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا الْعِدَّةَ وَاتَّقُوا اللَّهَ رَبَّكُمْ لَا تُخْرِجُوهُنَّ مِنْ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ إِلَّا أَنْ يَأْتِينَ بِفَاحِشَةٍ مُبَيِّنَةٍ وَتِلْكَ حُدُودُ اللَّهِ وَمَنْ يَتَعَدَّ حُدُودَ اللَّهِ فَقَدْ ظَلَمَ نَفْسَهُ لَا تَدْرِي لَعَلَّ اللَّهَ يُحْدِثُ بَعْدَ ذَلِكَ أَمْرًا", "2": "فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ فَارِقُوهُنَّ بِمَعْرُوفٍ وَأَشْهِدُوا ذَوَيْ عَدْلٍ مِنْكُمْ وَأَقِيمُوا الشَّهَادَةَ لِلَّهِ ذَلِكُمْ يُوعَظُ بِهِ مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا", "3": "وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ وَمَنْ يَتَوَكَّلْ عَلَى اللَّهِ فَهُوَ حَسْبُهُ إِنَّ اللَّهَ بَالِغُ أَمْرِهِ قَدْ جَعَلَ اللَّهُ لِكُلِّ شَيْءٍ قَدْرًا", "4": "وَاللَّائِي يَئِسْنَ مِنَ الْمَحِيضِ مِنْ نِسَائِكُمْ إِنِ ارْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَاثَةُ أَشْهُرٍ وَاللَّائِي لَمْ يَحِضْنَ وَأُولَاتُ الْأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا", "5": "ذَلِكَ أَمْرُ اللَّهِ أَنْزَلَهُ إِلَيْكُمْ وَمَنْ يَتَّقِ اللَّهَ يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُعْظِمْ لَهُ أَجْرًا", "6": "أَسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنْتُمْ مِنْ وُجْدِكُمْ وَلَا تُضَارُّوهُنَّ لِتُضَيِّقُوا عَلَيْهِنَّ وَإِنْ كُنَّ أُولَاتِ حَمْلٍ فَأَنْفِقُوا عَلَيْهِنَّ حَتَّى يَضَعْنَ حَمْلَهُنَّ فَإِنْ أَرْضَعْنَ لَكُمْ فَآتُوهُنَّ أُجُورَهُنَّ وَأْتَمِرُوا بَيْنَكُمْ بِمَعْرُوفٍ وَإِنْ تَعَاسَرْتُمْ فَسَتُرْضِعُ لَهُ أُخْرَى", "7": "لِيُنْفِقْ ذُو سَعَةٍ مِنْ سَعَتِهِ وَمَنْ قُدِرَ عَلَيْهِ رِزْقُهُ فَلْيُنْفِقْ مِمَّا آتَاهُ اللَّهُ لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا مَا آتَاهَا سَيَجْعَلُ اللَّهُ بَعْدَ عُسْرٍ يُسْرًا", "8": "وَكَأَيِّنْ مِنْ قَرْيَةٍ عَتَتْ عَنْ أَمْرِ رَبِّهَا وَرُسُلِهِ فَحَاسَبْنَاهَا حِسَابًا شَدِيدًا وَعَذَّبْنَاهَا عَذَابًا نُكْرًا", "9": "فَذَاقَتْ وَبَالَ أَمْرِهَا وَكَانَ عَاقِبَةُ أَمْرِهَا خُسْرًا", "10": "أَعَدَّ اللَّهُ لَهُمْ عَذَابًا شَدِيدًا فَاتَّقُوا اللَّهَ يَاأُولِي الْأَلْبَابِ الَّذِينَ آمَنُوا قَدْ أَنْزَلَ اللَّهُ إِلَيْكُمْ ذِكْرًا", "11": "رَسُولًا يَتْلُو عَلَيْكُمْ آيَاتِ اللَّهِ مُبَيِّنَاتٍ لِيُخْرِجَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ مِنَ الظُّلُمَاتِ إِلَى النُّورِ وَمَنْ يُؤْمِنْ بِاللَّهِ وَيَعْمَلْ صَالِحًا يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا قَدْ أَحْسَنَ اللَّهُ لَهُ رِزْقًا", "12": "اللَّهُ الَّذِي خَلَقَ سَبْعَ سَمَاوَاتٍ وَمِنَ الْأَرْضِ مِثْلَهُنَّ يَتَنَزَّلُ الْأَمْرُ بَيْنَهُنَّ لِتَعْلَمُوا أَنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ وَأَنَّ اللَّهَ قَدْ أَحَاطَ بِكُلِّ شَيْءٍ عِلْمًا"}, "units": [{"aya": 1, "title": "في معنى الفاحشة التي ذكرت في هذا الموضع، والمعنى الذي من أجله أذن الله بإخراجهن في حال كونهن في العدة من بيوتهن", "tabari": {"page": "23/32", "sarih": 1, "tarjih": "والصواب من القول في ذلك عندي قول من قال: عني بالفاحشة في هذا الموضع المعصية. وذلك أن الفاحشة هي كل أمر قبيح تعدي فيه حده، فالزنى من ذلك، والسرق والبذاء على الأحماء وخروجها متحولة عن منزلها الذي يلزمها أن تعتد فيه، منه، فأي ذلك فعلت وهي في عدتها، فلزوجها إخراجها من بيتها، ذلك لإتيانها بالفاحشة التي ركبتها.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "الفاحشة التي ذكر الله ﷿ في هذا الموضع هي الزنى، والإخراج الذي أباح الله هو الإخراج لإقامة الحد", "taqdim": 0, "n_athar": 5, "qailun": [["الحسن", "تابعي"], ["صالح بن مسلم", ""], ["مجاهد", "تابعي"]], "athar": [77157, 77159, 77160, 77178, 77181, 77185, 77201, 77202, 77218, 77230, 77234, 77261, 77264]}, {"n": 2, "t": "الفاحشة التي عناها الله ﷿ في هذا الموضع البذاء على أحمائها", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [77156, 77161, 77173, 77174, 77175, 77176, 77199, 77200, 77226, 77227, 77229]}, {"n": 3, "t": "بل هي كل معصية لله", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [77156, 77161, 77173, 77174, 77175, 77176, 77199, 77200, 77226, 77227, 77229]}, {"n": 4, "t": "بل ذلك نشوزها على زوجها، فيطلقها على النشوز، فيكون لها التحول حينئذ من بيتها", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [77186, 77187, 77188, 77220, 77224, 77241, 77242, 77265, 77266, 77267]}, {"n": 5, "t": "الفاحشة المبينة التي ذكر الله ﷿ في هذا الموضع خروجها من بيتها", "taqdim": 0, "n_athar": 2, "qailun": [["السدي", "تابعي"], ["عبد الله بن عمر", "صحابي"]], "athar": [77155, 77158, 77163, 77164, 77167, 77169, 77177, 77189, 77205, 77211, 77222, 77232, 77244, 77268]}]}, "mawaqif": [{"taliq": 6651, "mi": 1, "aya": 1, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "23/ 36", "qawl": "العموم", "nass": "الصواب من القول في ذلك عندي قول من قال: عنى بالفاحشة في هذا الموضع: المعصية. وذلك أن الفاحشة هي كل أمر قبيح تعدي فيه حده، فالزنا من ذلك، والسرق والبذاء على الأحماء، وخروجها متحولة عن منزلها الذي يلزمها أن تعتد فيه منه، فأي ذلك فعلت وهي في عدتها فلزوجها إخراجها من بيتها؛ ذلك لإتيانها بالفاحشة التي ركبتها", "qawaid": ["اللغة", "العموم"], "tabi": ""}, {"taliq": 6651, "mi": 1, "aya": 1, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "14/ 28", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}], "mushid": {"i": 1, "imgs": ["065_001_1.png"], "pages": [516], "n": 5, "rajih": [3], "daif": [], "match": true}, "mawsua": {"taliq": 6651, "masala": "معنى «الفاحشة» في هذا الموضع", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنها الزنا، والإخراج -على ذلك- هو الإخراج لإقامة الحد", "ashab": "", "athar": []}, {"n": 2, "t": "أنها البذاء على أحمائها", "ashab": "", "athar": []}, {"n": 3, "t": "أنها كل معصية لله", "ashab": "", "athar": []}, {"n": 4, "t": "أنها نشوز المرأة على زوجها", "ashab": "", "athar": []}, {"n": 5, "t": "أنها خروج المرأة من بيتها قبل انقضاء عدتها", "ashab": "", "athar": []}]}, "tags": {"m": {"3": [["ابن جرير", "r"]]}, "t": {"3": [["ابن جرير", "r"]]}, "gen": [["ابن جرير", "رجّح العموم"], ["ابن كثير", "رجّح العموم"]], "rules": {"ابن جرير": ["اللغة", "العموم"]}, "rulesD": {}}}, {"aya": 1, "title": "البداية بالنبي، ثم قوله تعالى بعد ذلك: {طلقتم}", "mawsua": {"taliq": 6646, "masala": "البداية بالنبي، ثم قوله تعالى بعد ذلك: {طلقتم}", "sigha": "حكاية خلاف", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "ذلك خروج من مخاطبة أفراد إلى مخاطبة جماعة، وهذا موجود", "ashab": "بعض النحويين -حكاه الزهراوي-", "athar": []}, {"n": 2, "t": "إن نداء النبي صلى الله عليه وسلم أريدت أمته معه، فلذلك قال تعالى: {طلقتم}", "ashab": "آخرون منهم", "athar": []}, {"n": 3, "t": "إن المعنى: يا أيها النبي قل لهم: {إذا طلقتم}", "ashab": "آخرون منهم", "athar": []}, {"n": 4, "t": "إنه من حيث يقول الرجل العظيم: فعلنا، وضعنا، خوطب النبي صلى الله عليه وسلم في هذه ب {طلقتم} إظهارا لتعظيمه، وهذا على نحو قوله تعالى في عبد الله بن أبي: {هم الذين يقولون} [المنافقون: 7] إذا كان قوله مما يقوله جماعة، فكذلك النبي في هذه الآية ما يخاطب به فهو خطاب لجماعة. والذي يظهر لي في هذا أنهما خطابان مفترقان، خوطب النبي على معنى تنبيه لسماع القول وتلقي الأمر، ثم قيل له: {إذا طلقتم} أي: أنت وأمتك، فقوله: {إذا طلقتم} ابتداء كلام لو ابتدأ السورة به. وطلاق النساء حل عصمتهن", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 6646, "mi": 0, "aya": 1, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 326 - 327 بتصرف", "qawl": "", "nass": "اختلف في البداية بالنبي، ثم قوله تعالى بعد ذلك: {طلقتم}؛ فقال بعض النحويين -حكاه الزهراوي-: ذلك خروج من مخاطبة أفراد إلى مخاطبة جماعة، وهذا موجود. وقال آخرون منهم: إن نداء النبي صلى الله عليه وسلم أريدت أمته معه، فلذلك قال تعالى: {طلقتم}. وقال آخرون منهم: إن المعنى: يا أيها النبي قل لهم: {إذا طلقتم}. وقال آخرون: إنه من حيث يقول الرجل العظيم: فعلنا، وضعنا، خوطب النبي صلى الله عليه وسلم في هذه ب {طلقتم} إظهارا لتعظيمه، وهذا على نحو قوله تعالى في عبد الله بن أبي: {هم الذين يقولون} [المنافقون: 7] إذا كان قوله مما يقوله جماعة، فكذلك النبي في هذه الآية ما يخاطب به فهو خطاب لجماعة. والذي يظهر لي في هذا أنهما خطابان مفترقان، خوطب النبي على معنى تنبيه لسماع القول وتلقي الأمر، ثم قيل له: {إذا طلقتم} أي: أنت وأمتك، فقوله: {إذا طلقتم} ابتداء كلام لو ابتدأ السورة به. وطلاق النساء حل عصمتهن", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 4, "title": "في معنى قوله: ﴿إن ارتبتم﴾", "tabari": {"page": "23/49", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصحة قول من قال: عنى بذلك: إن ارتبتم فلم تدروا ما الحكم فيهن. وذلك أن معنى ذلك لو كان كما قاله من قال: إن ارتبتم بدمائهن فلم تدروا أدم حيض أو استحاضة. لقيل: إن ارتبتن ؛ لأنهن إذا أشكل الدم عليهن، فهن المرتابات بدماء أنفسهن لا غيرهن. وفي قوله: ﴿إن ارتبتم﴾، وخطابه الرجال بذلك دون النساء، الدليل الواضح على صحة ما قلنا، من أن معناه: إن ارتبتم أنتم أيها الرجال بالحكم فيهن. وأخرى؛ وهو أنه جل ثناؤه قال: ﴿واللائي يئسن من المحيض من نسائكم إن ارتبتم﴾. واليائسة من المحيض هي التي لا ترجو محيضا لكبر ، ومحال أن يقال: واللائي يئسن. ثم يقال: إن ارتبتم بيأسهن ؛ لأن اليأس هو انقطاع الرجاء، والمرتاب بيأسها مرجو لها، وغير جائز ارتفاع الرجاء ووجوده في وقت واحد [في شخص واحد] . فإذا كان الصواب من القول في ذلك ما قلنا، فبين أن تأويل الآية: واللائي يئسن من المحيض من نسائكم، إن ارتبتم بالحكم فيهن وفي عددهن، فلم تدروا ما هو ، فإن حكم عددهن إذا طلقن وهن ممن قد دخل بهن أزواجهن، فعدتهن ثلاثة أشهر. ﴿واللائي لم يحضن﴾. يقول: وكذلك عدد اللائي لم يحضن من الجواري لصغرهن ، إذا طلقهن أزواجهن بعد الدخول.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "معنى ذلك: إن ارتبتم بالدم الذي يظهر منها لكبرها؛ أمن الحيض هو أم من الاستحاضة، فعدتهن ثلاثة أشهر", "taqdim": 0, "n_athar": 4, "qailun": [["مجاهد", "تابعي"], ["الزهري", "تابعي"], ["ابن زيد", "تابع التابعين"], ["المرتابة", ""]], "athar": [77350, 77351, 77364]}, {"n": 2, "t": "بل معنى ذلك: إن ارتبتم بحكمهن، فلم تدروا ما الحكم في عدتهن، فإن عدتهن ثلاثة أشهر", "taqdim": 0, "n_athar": 1, "qailun": [["عمرو بن سالم", ""]], "athar": []}, {"n": 3, "t": "معنى ذلك: إن ارتبتم بما يظهر منهن من الدم، فلم تدروا أدم حيض، أم دم استحاضة ، من كبر كان ذلك أو علة؟", "taqdim": 0, "n_athar": 4, "qailun": [["عكرمة", "تابعي"], ["السدي", "تابعي"], ["قتادة", "تابعي"]], "athar": [77357, 77359, 77399, 77400, 77401, 77402]}]}, "mawaqif": [{"taliq": 6661, "mi": 1, "aya": 4, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "23/ 52 - 53", "qawl": "الثاني", "nass": "أولى الأقوال في ذلك بالصحة قول من قال: عني بذلك: إن ارتبتم فلم تدروا ما الحكم فيهن. وذلك أن معنى ذلك لو كان كما قاله من قال: إن ارتبتم بدمائهن فلم تدروا أدم حيض، أو استحاضة؟ لقيل: إن ارتبتن. لأنهن إذا أشكل الدم عليهن فهن المرتابات بدماء أنفسهن لا غيرهن، وفي قوله: {إن ارتبتم} وخطابه الرجال بذلك دون النساء الدليل الواضح على صحة ما قلنا من أن معناه: إن ارتبتم أيها الرجال بالحكم فيهن. وأخرى: وهو أنه -جل ثناؤه- قال: {واللائي يئسن من المحيض من نسائكم إن ارتبتم} واليائسة من المحيض هي التي لا ترجو محيضا للكبر، ومحال أن يقال: {واللائي يئسن}، ثم يقال: ارتبتم بيأسهن. لأن اليأس: هو انقطاع الرجاء، والمرتاب بيأسها مرجو لها، وغير جائز ارتفاع الرجاء ووجوده في وقت واحد، فإذا كان الصواب من القول في ذلك ما قلنا، فبين أن تأويل الآية: {واللائي يئسن من المحيض من نسائكم إن ارتبتم} بالحكم فيهن، وفي عددهن، فلم تدروا ما هو، فإن حكم عددهن إذا طلقن، وهن ممن دخل بهن أزواجهن فعدتهن ثلاثة أشهر", "qawaid": ["ظاهر الآية ولفظها", "الدلالة العقلية"], "tabi": ""}, {"taliq": 6661, "mi": 1, "aya": 4, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 331 - 332", "qawl": "", "nass": "اليائسات من المحيض على مراتب: فيائسة هو أول يأسها، فهذه ترفع إلى السنة، ويبقيها الاحتياط على حكم من ليست بيائسة؛ لأنا لا ندري لعل الدم يعود. ويائسة قد انقطع عنها الدم؛ لأنها طعنت في السن، ثم طلقت، وقد مرت عادتها بانقطاع الدم، إلا أنها مما يخاف أن تحمل نادرا، فهذه التي في الآية على أحد التأويلين في قوله: {إن ارتبتم}، وهو قول من يجعل الارتياب بأمر الحمل، وهو الأظهر. ويائسة قد هرمت حتى تتيقن أنها لا تحمل، فهذه ليست في الآية؛ لأنها لا يرتاب بحملها، لكنها في حكم الأشهر الثلاثة إجماعا فيما علمت، وهي في الآية على تأويل من يرى قوله: {إن ارتبتم} معناه في حكم اليائسات", "qawaid": [], "tabi": ""}], "mushid": {"i": 2, "imgs": ["065_002_1.png"], "pages": [516], "n": 3, "rajih": [2], "daif": [], "match": true}, "mawsua": {"taliq": 6661, "masala": "معنى قوله: {إن ارتبتم}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن معنى ذلك: إن ارتبتم بالدم الذي يظهر منها لكبرها، أمن الحيض هو، أم من الاستحاضة", "ashab": "مجاهد، والزهري، وابن زيد", "athar": [77350, 77364]}, {"n": 2, "t": "أن معنى ذلك: إن ارتبتم بحكمهن، فلم تدروا ما الحكم في عدتهن", "ashab": "أبي", "athar": [77346, 77347, 77362, 77367]}, {"n": 3, "t": "أن معنى ذلك: إن ارتبتم بالدم الذي يظهر منها، أمن الحيض هو، أم من الاستحاضة؟ من كبر كان ذلك أم من علة؟", "ashab": "عكرمة، وقتادة", "athar": [77357]}]}, "tags": {"m": {"2": [["ابن جرير", "r"]]}, "t": {"2": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["ظاهر الآية ولفظها", "الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 4, "title": "تأويل: ﴿وأولات الأحمال أجلهن أن يضعن حملهن﴾", "tabari": {"page": "23/57", "sarih": 0, "tarjih": "والصواب من القول في ذلك عندنا: أنه عام في المطلقات والمتوفى عنهن؛ لأن الله - جل وعز - عم القول بذلك، فقال: ﴿وأولات الأحمال أجلهن أن يضعن حملهن﴾. ولم يخصص بذلك الخبر عن مطلقة دون متوفى عنها، بل عم الخبر به عن جميع أولات الأحمال. فإن ظن ظان أن قوله: ﴿وأولات الأحمال أجلهن أن يضعن حملهن﴾ في سياق الخبر عن أحكام المطلقات دون المتوفى عنهن؛ فهو بالخبر عن حكم المطلقة أولى [من الخبر] عنهن، وعن المتوفى عنهن - فإن الأمر بخلاف ما ظن؛ وذلك أن ذلك وإن كان في سياق الخبر عن أحكام المطلقات، فإنه منقطع عن الخبر عن أحكام المطلقات، بل هو خبر مبتدأ عن أحكام عدد جميع أولات الأحمال المطلقات منهن وغير المطلقات، ولا دلالة على أنه مراد به بعض الحوامل دون بعض، من خبر ولا عقل، فهو على عمومه لما بينا.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "﴿وأولات الأحمال أجلهن أن يضعن حملهن﴾. قال: قلت: يا رسول الله، المتوفى عنها زوجها والمطلقة؟ قال: \"نعم\" .", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "ذلك خاص في المطلقات، وأما المتوفى عنها فإن عدتها آخر الأجلين. وذلك قول مروي عن علي وابن عباس ﵄", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 6662, "mi": 1, "aya": 4, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "23/ 58", "qawl": "الأول", "nass": "الصواب من القول في ذلك أنه عام في المطلقات والمتوفى عنهن؛ لأن الله -جل وعز- عم القول بذلك، فقال: {وأولات الأحمال أجلهن أن يضعن حملهن} ولم يخصص بذلك الخبر عن مطلقة دون متوفى عنها، بل عم الخبر به عن جميع أولات الأحمال. فإن ظن ظان أن قوله: {وأولات الأحمال أجلهن أن يضعن حملهن} في سياق الخبر عن أحكام المطلقات دون المتوفى عنهن، فهو بالخبر عن حكم المطلقة أولى من الخبر عنهن، وعن المتوفى عنهن- فإن الأمر بخلاف ما ظن، وذلك أن ذلك وإن كان في سياق الخبر عن أحكام المطلقات، فإنه منقطع عن الخبر عن أحكام المطلقات، بل هو خبر مبتدأ عن أحكام عدد جميع أولات الأحمال المطلقات منهن وغير المطلقات، ولا دلالة على أنه مراد به بعض الحوامل دون بعض من خبر ولا عقل، فهو على عمومه لما بينا", "qawaid": ["العموم"], "tabi": ""}], "mushid": {"i": 3, "imgs": ["065_003_1.png"], "pages": [517], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 6662, "masala": "حكم قوله تعالى: {وأولات الأحمال أجلهن أن يضعن حملهن}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه عام في المطلقات والمتوفى عنهن", "ashab": "ابن مسعود، والجمهور", "athar": [77385, 77386, 77387, 77388, 77389]}, {"n": 2, "t": "أنه خاص في المطلقات، وأما المتوفى عنها فإن عدتها آخر الأجلين", "ashab": "علي، وابن عباس", "athar": [77383, 77411]}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["العموم"]}, "rulesD": {}}}, {"aya": 6, "title": "تأويل: ﴿وإن كن أولات حمل فأنفقوا عليهن حتى يضعن حملهن﴾", "tabari": {"page": "23/63", "sarih": 0, "tarjih": "والصواب من القول في ذلك عندنا أن لا نفقة للمبتوتة، إلا أن تكون حاملا؛ لأن الله جل ثناؤه جعل النفقة بقوله: ﴿وإن كن أولات حمل فأنفقوا عليهن﴾. للحوامل دون غيرهن من البائنات من أزواجهن، ولو كان البوائن من الحوامل وغير الحوامل في الواجب لهن من النفقة على أزواجهن سواء، لم يكن لخصوص أولات الأحمال بالذكر في هذا الموضع وجه مفهوم؛ إذ هن وغيرهن في ذلك سواء، وفي خصوصهن بالذكر دون غيرهن أدل الدليل على أن لا نفقة لبائن إلا أن تكون حاملا.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "﴿وإن كن أولات حمل فأنفقوا عليهن حتى يضعن حملهن﴾. يقول تعالى ذكره: وإن كان نساؤكم المطلقات أولات حمل، وكن بائنات منكم، فأنفقوا عليهن في عدتهن منكم حتى يضعن حملهن.", "taqdim": 1, "n_athar": 2, "qailun": [["ابن عباس", "صحابي"], ["السدي", "تابعي"]], "athar": [77414, 77417, 77422, 77426, 77430, 77436, 77439, 77447, 77452]}, {"n": 2, "t": "عني بقوله: ﴿وإن كن أولات حمل فأنفقوا عليهن حتى يضعن حملهن﴾ كل مطلقة، ملك زوجها رجعتها أو لم يملك", "taqdim": 0, "n_athar": 4, "qailun": [["إبراهيم", "تابعي"]], "athar": [77424, 77428, 77433, 77444]}]}, "mawaqif": [], "mushid": {"i": 4, "imgs": ["065_004_1.png"], "pages": [517], "n": 2, "rajih": [1], "daif": [], "match": true}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 8, "title": "تأويل: ﴿وكأين من قرية عتت عن أمر ربها ورسله﴾", "tabari": {"page": "23/72", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿وكأين من قرية عتت عن أمر ربها ورسله﴾. يقول تعالى ذكره: وكم من أهل قرية طغوا عن أمر ربهم وخالفوه، وعن أمر رسل ربهم، فتمادوا في طغيانهم وعتوهم، ولجوا في كفرهم.", "taqdim": 1, "n_athar": 2, "qailun": [["السدي", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [77468, 77471, 77473, 77475]}, {"n": 2, "t": "إنهم كانوا قوما خالفوا أمر ربهم في الطلاق، فتوعد الله بالخبر عنهم هذه الأمة، أن يفعل بهم فعله بهم إن خالفوا أمره في ذلك", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 10, "title": "في المعني بالذكر والرسول في هذا الموضع ﴿قد أنزل الله إليكم ذكرا (١٠) رسولا﴾", "tabari": {"page": "23/75", "sarih": 1, "tarjih": "والصواب من القول في ذلك عندنا، أن الرسول ترجمة عن الذكر، ولذلك نصب؛ لأنه مردود عليه على البيان عنه والترجمة.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "الذكر القرآن، والرسول محمد ﷺ", "taqdim": 0, "n_athar": 2, "qailun": [["السدي", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [77483, 77487]}, {"n": 2, "t": "الذكر هو الرسول ﷺ", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 6667, "mi": 0, "aya": 10, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "8/ 335", "qawl": "", "nass": "الذكر", "qawaid": [], "tabi": ""}, {"taliq": 6667, "mi": 0, "aya": 10, "alam": "ابن جرير", "fil": "ذهب", "kind": "قول", "ref": "23/ 76", "qawl": "", "nass": "الصواب من القول في ذلك أن الرسول ترجمة عن الذكر، ولذلك نصب؛ لأنه مردود عليه على البيان عنه والترجمة. فتأويل الكلام إذن: قد أنزل الله إليكم -يا أولي الألباب- ذكرا من الله لكم يذكركم به، وينبهكم على حظكم من الإيمان بالله، والعمل بطاعته، رسولا يتلو عليكم آيات الله التي أنزلها عليه مبينات لمن سمعها وتدبرها أنها من عند الله", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 6667, "mi": 0, "aya": 10, "alam": "ابن عطية", "fil": "ذهب", "kind": "قول", "ref": "8/ 336", "qawl": "", "nass": "أبين الأقوال عندي معنى أن يكون الذكر: القرآن، والرسول: محمدا صلى الله عليه وسلم، والمعنى: بعث رسولا، لكن الإيجاز اقتضى اختصار الفعل الناصب للرسول، ونحا هذا المنحى السدي", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}], "mushid": {"i": 5, "imgs": ["065_005_1.png"], "pages": [517], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {"ابن جرير": ["اللغة"], "ابن عطية": ["لم يذكر مستندًا"]}, "rulesD": {}}}], "extra": [], "others": {"0": [{"id": 6643, "kinds": "نقل", "text": "نقل ابنُ عطية (8/ 326) الإجماعَ على مدنيّة سورة الطَّلاق، فقال: «هي مدنيّة بإجماع من أهل التفسير».\nوقد نُصَّ على مدنية السورة أيضًا في تفسير ابن كثير (14/ 26).", "mawaqif": [{"taliq": 6643, "mi": 0, "aya": 0, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "8/ 326", "qawl": "", "nass": "هي مدنية بإجماع من أهل التفسير", "qawaid": [], "tabi": ""}]}], "1": [{"id": 6644, "kinds": "تعليق", "text": "عَلَّقَ ابنُ عطية (8/ 327) على هذا القراءة بقوله: «أي: لاستقبالها».", "mawaqif": [{"taliq": 6644, "mi": 0, "aya": 1, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "8/ 327", "qawl": "", "nass": "أي: لاستقبالها", "qawaid": [], "tabi": ""}]}, {"id": 6645, "kinds": "تعليق", "text": "عَلَّقَ ابنُ كثير (14/ 27) على أثر ابن عمر بأنه: «أمسُّ لفظٍ يُورد ها هنا».", "mawaqif": [{"taliq": 6645, "mi": 0, "aya": 1, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "14/ 27", "qawl": "", "nass": "أمس لفظ يورد ها هنا", "qawaid": [], "tabi": ""}]}, {"id": 6647, "kinds": "غيره", "text": "قال ابنُ كثير (14/ 28) تعليقًا على هذه الآثار: «من هاهنا أخذ الفقهاء أحكام الطَّلاق، وقسّموه إلى طلاق سُنَّة وطلاق بدعة، فطلاق السُّنَّة: أن يطلَّقها طاهرة من غير جماع، أو حاملًا قد استبان حمْلها. والبدعة: هو أن يُطلِّقها في حال الحيض، أو في طُهرٍ قد جامعها فيه ولا يدري أحمَلت أم لا. وطلاق ثالث لا سنة فيه ولا بدعة: وهو طلاق الصغيرة، والآيسة، وغير المدخول بها».", "mawaqif": [{"taliq": 6647, "mi": 0, "aya": 1, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "14/ 28", "qawl": "", "nass": "من هاهنا أخذ الفقهاء أحكام الطلاق، وقسموه إلى طلاق سنة وطلاق بدعة، فطلاق السنة: أن يطلقها طاهرة من غير جماع، أو حاملا قد استبان حملها. والبدعة: هو أن يطلقها في حال الحيض، أو في طهر قد جامعها فيه ولا يدري أحملت أم لا. وطلاق ثالث لا سنة فيه ولا بدعة: وهو طلاق الصغيرة، والآيسة، وغير المدخول بها", "qawaid": [], "tabi": ""}]}, {"id": 6648, "kinds": "نقل", "text": "قال ابنُ عطية (8/ 326): «الطَّلاق على الجملة مكروه؛ لأنه تبديد شمْلٍ في الإسلام، وروى أبو موسى الأشعري أنّ النبي صلى الله عليه وسلم قال: «لا تطلَّقوا النساء إلا من رِيبة؛ فإن الله لا يحب الذّواقين ولا الذّواقات». وروى أنس أنه عليه السلام قال: «ما حلف بالطَّلاق، ولا استحلف به إلا منافق»».وقال ابنُ عطية (8/ 327): «معنى هذه الآية: أن لا يُطلَّق أحدٌ امرأته إلا في طُهرٍ لم يَمسّها فيه، هذا على مذهب مالك وغيره ممن قال بأن الأقراء: الأطهار، فيُطلِّق عندهم المطلِّق في طُهرٍ لم يمسّ فيه وتعتد به المرأة، ثم تَحيض حيضتين تُعتدّ بالطُّهر الذي بينهما، ثم تقيم في الطُّهر الثالث معتدة به، فإذا رأتْ أول الحَيْضة الثالثة حلَّت، ومَن قال: بأن الأقراء: الحيض -وهم العراقيون- قال: {لعدتهن} معناه: أن تُطلَّق طاهرًا، فتستقبل ثلاث حِيض كوامل، فإذا رأت الطُّهر بعد الثالثة حلَّتْ، ويخفُّ عند هؤلاء مسّ في طُهر الطَّلاق أو لم يمسّ، وكذلك مالك يقول: إن طلَّق في طُهر قد مسّ فيه مضى الطَّلاق. ولا يجوز طلاق الحائض؛ لأنها تطول العِدّة عليها، وقيل: بل تعتدّ، ولو علل بالتطويل لا ينبغي أن يجوز ولو رضيته، والأصل في ذلك حديث عبد الله بن عمر قال: «طلَّقت امرأتي وهي حائض … »».", "mawaqif": [{"taliq": 6648, "mi": 0, "aya": 1, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 326", "qawl": "", "nass": "الطلاق على الجملة مكروه؛ لأنه تبديد شمل في الإسلام، وروى أبو موسى الأشعري أن النبي صلى الله عليه وسلم قال: «لا تطلقوا النساء إلا من ريبة؛ فإن الله لا يحب الذواقين ولا الذواقات", "qawaid": [], "tabi": ""}, {"taliq": 6648, "mi": 0, "aya": 1, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 327", "qawl": "", "nass": "معنى هذه الآية: أن لا يطلق أحد امرأته إلا في طهر لم يمسها فيه، هذا على مذهب مالك وغيره ممن قال بأن الأقراء: الأطهار، فيطلق عندهم المطلق في طهر لم يمس فيه وتعتد به المرأة، ثم تحيض حيضتين تعتد بالطهر الذي بينهما، ثم تقيم في الطهر الثالث معتدة به، فإذا رأت أول الحيضة الثالثة حلت، ومن قال: بأن الأقراء: الحيض -وهم العراقيون- قال: {لعدتهن} معناه: أن تطلق طاهرا، فتستقبل ثلاث حيض كوامل، فإذا رأت الطهر بعد الثالثة حلت، ويخف عند هؤلاء مس في طهر الطلاق أو لم يمس، وكذلك مالك يقول: إن طلق في طهر قد مس فيه مضى الطلاق. ولا يجوز طلاق الحائض؛ لأنها تطول العدة عليها، وقيل: بل تعتد، ولو علل بالتطويل لا ينبغي أن يجوز ولو رضيته، والأصل في ذلك حديث عبد الله بن عمر قال: «طلقت امرأتي وهي حائض … »", "qawaid": [], "tabi": ""}]}, {"id": 6649, "kinds": "غيره", "text": "قال ابنُ تيمية (8/ 320 - 321): «لَمّا رأى عمرُ? أنّ المبتوتة لها السُّكنى والنّفقة فظنّ أنّ القرآن يدلّ عليه نازعه أكثر الصحابة، فمنهم مَن قال: لها السُّكنى فقط. ومنهم مَن قال: لا نفقة لها ولا سُكنى. وكان مِن هؤلاء ابن عباس، وجابر، وفاطمة بنت قيس، وهي التي روتْ عن النبي صلى الله عليه وسلم أنه قال: «ليس لكِ نفقة ولا سُكنى». فلمّا احتجوا عليها بحُجّة عمر، وهي قوله تعالى: {لا تخرجوهن من بيوتهن ولا يخرجن إلا أن يأتين بفاحشة مبينة}؛ قالت هي وغيرها من الصحابة -كابن عباس، وجابر، وغيرهما-: هذا في الرّجعية؛ لقوله تعالى: {لا تدري لعل الله يحدث بعد ذلك أمرًا} فأي أمر يُحدِث بعد الثلاث؟! وفقهاء الحديث كأحمد بن حنبل في ظاهر مذهبه وغيره من فقهاء الحديث مع فاطمة بنت قيس».", "mawaqif": [{"taliq": 6649, "mi": 0, "aya": 1, "alam": "ابن تيمية", "fil": "قال", "kind": "قول", "ref": "8/ 320 - 321", "qawl": "", "nass": "لما رأى عمر? أن المبتوتة لها السكنى والنفقة فظن أن القرآن يدل عليه نازعه أكثر الصحابة، فمنهم من قال: لها السكنى فقط. ومنهم من قال: لا نفقة لها ولا سكنى. وكان من هؤلاء ابن عباس، وجابر، وفاطمة بنت قيس، وهي التي روت عن النبي صلى الله عليه وسلم أنه قال: «ليس لك نفقة ولا سكنى", "qawaid": [], "tabi": ""}]}, {"id": 6650, "kinds": "غيره", "text": "قال ابنُ عطية (8/ 328): «سُنَّة ذلك أن لا تبيتَ المرأة المطلَّقة بعيدة عن بيتها، ولا تغيب عنه نهارًا إلا في ضرورة، وما لا خَطب له من جائز التصرف؛ وذلك لحفظ النسب والتحرز بالنساء، فإن كان البيت مِلكًا للزوج أو بِكِراءٍ منه فهذا حكمه، فإن كان لها فعليه الكِراء».", "mawaqif": [{"taliq": 6650, "mi": 0, "aya": 1, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 328", "qawl": "", "nass": "سنة ذلك أن لا تبيت المرأة المطلقة بعيدة عن بيتها، ولا تغيب عنه نهارا إلا في ضرورة، وما لا خطب له من جائز التصرف؛ وذلك لحفظ النسب والتحرز بالنساء، فإن كان البيت ملكا للزوج أو بكراء منه فهذا حكمه، فإن كان لها فعليه الكراء", "qawaid": [], "tabi": ""}]}, {"id": 6652, "kinds": "بيان،نقل", "text": "قال ابنُ عطية (8/ 329): «قوله تعالى: {لا تدري لعل الله يحدث بعد ذلك أمرًا}، قال قتادة وغيره: يريد به: الرجعة، أي: أحصوا العِدّة، وامتثلوا هذه الأوامر المثقِّفة لنسائكم، الحافظة لأنسابكم، وطلَّقوا على السُّنَّة تجدوا المخْلَص إن ندمتم؛ فإنكم لا تدرون لعل الرجعة تكون بَعْد، والإحداث في هذه الآية بين التوجه عبارة عما يوجد من التراجع. وجوَّز قوم أن يكون المعنى: أمرًا مِن النسخ. وفي ذلك بُعْد».\nوقال ابنُ تيمية (8/ 321): «لما قال تعالى: {لعل الله يحدث بعد ذلك أمرًا} قال غيرُ واحد من الصحابة والتابعين والعلماء: هذا يدلُّ على أنّ الطَّلاق الذي ذكره الله هو الطَّلاق الرجعي؛ فإنه لو شرع إيقاع الثلاث عليه لكان المطلِّق يندم إذا فعل ذلك، ولا سبيل إلى رجعتها، فيحصل له ضرر بذلك، واللهُ أمر العباد بما ينفعهم، ونهاهم عما يضرهم؛ ولهذا قال تعالى أيضًا بعد ذلك: {فإذا بلغن أجلهن فأمسكوهن بمعروف أو فارقوهن بمعروف} وهذا إنما يكون في الطَّلاق الرجعي، لا يكون في الثلاث، ولا في البائن».", "mawaqif": [{"taliq": 6652, "mi": 0, "aya": 1, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 329", "qawl": "", "nass": "قوله تعالى: {لا تدري لعل الله يحدث بعد ذلك أمرا}، قال قتادة وغيره: يريد به: الرجعة، أي: أحصوا العدة، وامتثلوا هذه الأوامر المثقفة لنسائكم، الحافظة لأنسابكم، وطلقوا على السنة تجدوا المخلص إن ندمتم؛ فإنكم لا تدرون لعل الرجعة تكون بعد، والإحداث في هذه الآية بين التوجه عبارة عما يوجد من التراجع. وجوز قوم أن يكون المعنى: أمرا من النسخ. وفي ذلك بعد", "qawaid": [], "tabi": ""}, {"taliq": 6652, "mi": 0, "aya": 1, "alam": "ابن تيمية", "fil": "قال", "kind": "قول", "ref": "8/ 321", "qawl": "", "nass": "لما قال تعالى: {لعل الله يحدث بعد ذلك أمرا} قال غير واحد من الصحابة والتابعين والعلماء: هذا يدل على أن الطلاق الذي ذكره الله هو الطلاق الرجعي؛ فإنه لو شرع إيقاع الثلاث عليه لكان المطلق يندم إذا فعل ذلك، ولا سبيل إلى رجعتها، فيحصل له ضرر بذلك، والله أمر العباد بما ينفعهم، ونهاهم عما يضرهم؛ ولهذا قال تعالى أيضا بعد ذلك: {فإذا بلغن أجلهن فأمسكوهن بمعروف أو فارقوهن بمعروف} وهذا إنما يكون في الطلاق الرجعي، لا يكون في الثلاث، ولا في البائن", "qawaid": [], "tabi": ""}]}], "2": [{"id": 6653, "kinds": "غيره", "text": "قال ابنُ عطية (8/ 329 - 330): «قوله تعالى: {وأشهدوا ذوي عدل منكم} يريد: على الرَّجعة، وذلك شرط في صحة الرَّجعة، وللمرأة منْع الزوج من نفسها حتى يُشهِد. وقال ابن عباس: المراد على الرجعة والطَّلاق؛ لأن الإشهاد يرفع من النوازل إشكالات كثيرة، وتقييد تاريخ الإشهاد من الإشهاد».", "mawaqif": [{"taliq": 6653, "mi": 0, "aya": 2, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 329 - 330", "qawl": "", "nass": "قوله تعالى: {وأشهدوا ذوي عدل منكم} يريد: على الرجعة، وذلك شرط في صحة الرجعة، وللمرأة منع الزوج من نفسها حتى يشهد. وقال ابن عباس: المراد على الرجعة والطلاق؛ لأن الإشهاد يرفع من النوازل إشكالات كثيرة، وتقييد تاريخ الإشهاد من الإشهاد", "qawaid": [], "tabi": ""}]}, {"id": 6654, "kinds": "تعليق", "text": "عَلَّقَ ابنُ عطية (8/ 330) على أثر النَّخْعي بقوله: «هذا قول الفقهاء، والعَدْل حقيقة الذي لا يخاف إلا الله تعالى».", "mawaqif": [{"taliq": 6654, "mi": 0, "aya": 2, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "8/ 330", "qawl": "", "nass": "هذا قول الفقهاء، والعدل حقيقة الذي لا يخاف إلا الله تعالى", "qawaid": [], "tabi": ""}]}, {"id": 6655, "kinds": "غيره", "text": "قال ابنُ جرير (23/ 42) مبيّنًا معنى الآية استنادًا إلى أثر السُّدِّيّ: «عني بقوله: {من كان يؤمن بالله}: مَن كانت صفته الإيمان بالله».", "mawaqif": [{"taliq": 6655, "mi": 0, "aya": 2, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "23/ 42", "qawl": "", "nass": "عني بقوله: {من كان يؤمن بالله}: من كانت صفته الإيمان بالله", "qawaid": ["أقوال السلف"], "tabi": ""}]}, {"id": 6656, "kinds": "خلاف", "text": "قال ابنُ عطية (8/ 330): «اختلفتْ ألفاظُ رواة هذه القصة عن ابن عباس رضي الله عنهما، لكن هذا هو المعنى».", "mawaqif": [{"taliq": 6656, "mi": 0, "aya": 2, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 330", "qawl": "", "nass": "اختلفت ألفاظ رواة هذه القصة عن ابن عباس رضي الله عنهما، لكن هذا هو المعنى", "qawaid": [], "tabi": ""}]}, {"id": 6657, "kinds": "تعليق", "text": "عَلَّقَ ابنُ القيم (3/ 163) على أثر أبي العالية بقوله: «هذا جامِعٌ لشدائد الدنيا والآخرة، ومضايق الدنيا والآخرة؛ فإنّ الله يجعل للمُتَّقي مِن كلِّ ما ضاق على الناس واشتد عليهم في الدنيا والآخرة مخرجًا».", "mawaqif": [{"taliq": 6657, "mi": 0, "aya": 2, "alam": "ابن القيم", "fil": "علق", "kind": "تعليق", "ref": "3/ 163", "qawl": "", "nass": "هذا جامع لشدائد الدنيا والآخرة، ومضايق الدنيا والآخرة؛ فإن الله يجعل للمتقي من كل ما ضاق على الناس واشتد عليهم في الدنيا والآخرة مخرجا", "qawaid": [], "tabi": ""}]}, {"id": 6658, "kinds": "بيان", "text": "قال ابنُ عطية (8/ 330): «قوله تعالى: {ومن يتق الله يجعل له مخرجًا ويرزقه من حيث لا يحتسب} قال عليُّ بن أبي طالب، وكثيرٌ من المتأولين: هو في معنى الطَّلاق، أي: ومَن لا يتعدى في طلاق السُّنَّة إلى طلاق الثلاث وغير ذلك يجعل الله له مخرجًا إن ندم بالرَّجعة، ويرزقه ما يُطعم أهله ويوسّع عليه، ومَن لا يتق الله فربّما طلَّق وبتَّ وندم، فلم يكن له مَخرجٌ، وزال عنه رِزق زوجته. وقد فسّر ابن عباس رضي الله عنهما نحو هذا».", "mawaqif": [{"taliq": 6658, "mi": 0, "aya": 2, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 330", "qawl": "", "nass": "قوله تعالى: {ومن يتق الله يجعل له مخرجا ويرزقه من حيث لا يحتسب} قال علي بن أبي طالب، وكثير من المتأولين: هو في معنى الطلاق، أي: ومن لا يتعدى في طلاق السنة إلى طلاق الثلاث وغير ذلك يجعل الله له مخرجا إن ندم بالرجعة، ويرزقه ما يطعم أهله ويوسع عليه، ومن لا يتق الله فربما طلق وبت وندم، فلم يكن له مخرج، وزال عنه رزق زوجته. وقد فسر ابن عباس رضي الله عنهما نحو هذا", "qawaid": [], "tabi": ""}]}], "3": [{"id": 6659, "kinds": "غيره", "text": "قال ابنُ جرير (23/ 47): «قوله: {إن الله بالغ أمره} منقطع عن قوله: {ومن يتوكل على الله فهو حسبه}. ومعنى ذلك: {إن الله بالغ أمره} بكلّ حال توكّل عليه العبد أو لم يتوكّل عليه».\nوبنحوه قال ابنُ عطية (8/ 331).", "mawaqif": [{"taliq": 6659, "mi": 0, "aya": 3, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "23/ 47", "qawl": "", "nass": "قوله: {إن الله بالغ أمره} منقطع عن قوله: {ومن يتوكل على الله فهو حسبه}. ومعنى ذلك: {إن الله بالغ أمره} بكل حال توكل عليه العبد أو لم يتوكل عليه", "qawaid": [], "tabi": ""}, {"taliq": 6659, "mi": 0, "aya": 3, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 331", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}]}, {"id": 6660, "kinds": "نقل", "text": "قال ابنُ القيم (3/ 165): «لما ذكر كفايته للمتوكّل عليه فربما أوهم ذلك تعجيل الكفاية وقت التوكّل، فعقّبه بقوله: {قد جعل الله لكل شيء قدرًا} أي: وقتًا لا يتعدّاه فهو يسوقه إلى وقته الذي قدَّره له. فلا يستعجل المتوكّل ويقول: قد توكلتُ، ودعوتُ فلم أر شيئًا ولم تحصل لي الكفاية، فالله بالغ أمره في وقته الذي قدَّره له».", "mawaqif": [{"taliq": 6660, "mi": 0, "aya": 3, "alam": "ابن القيم", "fil": "قال", "kind": "قول", "ref": "3/ 165", "qawl": "", "nass": "لما ذكر كفايته للمتوكل عليه فربما أوهم ذلك تعجيل الكفاية وقت التوكل، فعقبه بقوله: {قد جعل الله لكل شيء قدرا} أي: وقتا لا يتعداه فهو يسوقه إلى وقته الذي قدره له. فلا يستعجل المتوكل ويقول: قد توكلت، ودعوت فلم أر شيئا ولم تحصل لي الكفاية، فالله بالغ أمره في وقته الذي قدره له", "qawaid": [], "tabi": ""}]}], "6": [{"id": 6663, "kinds": "غيره", "text": "قال ابنُ عطية (8/ 333): «أمر الله تعالى بإسكان المطلَّقات، ولا خلاف في التي لم تُبَتّ، وأما المبتوتة، فمالك? يَرى لها السُّكنى لِمكان حِفظ النّسب، ولا يَرى لها نَفقة؛ لأنّ النّفقة بإزاء الاستمتاع. وهو قول الأوزاعي، والشافعي، وابن أبي ليلى، وأبي عبيد، وابن المسيّب، وعطاء، والشعبي، وسليمان بن يَسار. وقال أصحاب الرأي والثوري: لها السّكنى والنّفقة. وقال جماعة من العلماء: ليس لها سُكنى ولا نفقة».", "mawaqif": [{"taliq": 6663, "mi": 0, "aya": 6, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 333", "qawl": "", "nass": "أمر الله تعالى بإسكان المطلقات، ولا خلاف في التي لم تبت، وأما المبتوتة، فمالك? يرى لها السكنى لمكان حفظ النسب، ولا يرى لها نفقة؛ لأن النفقة بإزاء الاستمتاع. وهو قول الأوزاعي، والشافعي، وابن أبي ليلى، وأبي عبيد، وابن المسيب، وعطاء، والشعبي، وسليمان بن يسار. وقال أصحاب الرأي والثوري: لها السكنى والنفقة. وقال جماعة من العلماء: ليس لها سكنى ولا نفقة", "qawaid": [], "tabi": ""}]}, {"id": 6664, "kinds": "خلاف،ترجيح،توجيه", "text": "لخَّصَ ابنُ كثير (14/ 40) الخلاف في قوله تعالى: {وإنْ كُنَّ أُولاتِ حَمْلٍ فَأَنْفِقُوا عَلَيْهِنَّ حَتّى يَضَعْنَ حَمْلَهُنَّ}، فقال: «قال كثير من العلماء -منهم ابن عباس، وطائفة من السلف، وجماعات من الخلف-: هذه في البائن، إن كانت حاملًا أنفق عليها حتى تضع حملها، قالوا: بدليل أنّ الرّجعية تجب نفقتها سواء كانت حاملًا أو حائلًا. وقال آخرون: بل السياق كلّه في الرّجعيات، وإنما نصّ على وجوب الإنفاق على الحامل، وإن كانت رجعية؛ لأنّ الحمْل تطول مدته غالبًا فاحتيج إلى النصّ على وجوب الإنفاق إلى الوضع؛ لئلا يُتوهّم أنه إنما تجب النّفقة بمقدار مدة العِدّة».\nوظاهر كلام ابن جرير (23/ 64) أنه رجَّحَ القولَ الأوَّلَ -استنادًا إلى السنة، والدلالة العقلية- حيث قال: «الصواب مِن القول في ذلك عندنا أن لا نفقة للمبتوتة إلا أن تكون حاملًا؛ لأنّ الله -جلّ ثناؤه- جعل النفقة بقوله: {وإن كن أولات حمل فأنفقوا عليهن} للحوامل دون غيرهنّ من البائنات من أزواجهنّ، ولو كان البوائن من الحوامل وغير الحوامل في الواجب لهنّ من النّفقة على أزواجهنّ سواء، لم يكن لخصوص أُولات الأحمال بالذّكر في هذا الموضع وجه مفهوم؛ إذ هنّ وغيرهنّ في ذلك سواء، وفي خصوصهنّ بالذكر دون غيرهنّ أدل الدليل على أن لا نفقة لبائن إلا أن تكون حاملًا. وبالذي قلنا في ذلك صحَّ الخبرُ عن رسول الله صلى الله عليه وسلم».وقال ابنُ عطية (8/ 333): «أما الحامل فلا خلاف في وجوب سُكناها ونفقتها؛ بُتَّت أو لم تُبَتّ؛ لأنها مُبيّنة في الآية، واختلفوا في نفقة الحامل المُتوفّى عنها زوجها على قولين لعلماء الأمة: فمَنعها قوم، وأوجبها في التركة قوم».", "mawaqif": [{"taliq": 6664, "mi": 0, "aya": 6, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 333", "qawl": "", "nass": "أما الحامل فلا خلاف في وجوب سكناها ونفقتها؛ بتت أو لم تبت؛ لأنها مبينة في الآية، واختلفوا في نفقة الحامل المتوفى عنها زوجها على قولين لعلماء الأمة: فمنعها قوم، وأوجبها في التركة قوم", "qawaid": [], "tabi": ""}]}, {"id": 6665, "kinds": "توجيه", "text": "قال ابنُ تيمية (6/ 330): «هذه الآية توجب رِزق المُرتَضع على أبيه؛ لقوله: {وإن كن أولات حمل فأنفقوا عليهن حتى يضعن حملهن فإن أرضعن لكم فآتوهن أجورهن}، فأوجبَ نفقته حملًا ورضيعًا بواسطة الإنفاق على الحامل والمرضع؛ فإنه لا يمكن رِزقه بدون رِزق حامله ومرضعه».\nوقال (6/ 331): «ليس في كتاب الله إجارة منصوص عليها في شريعتنا إلا هذه الإجارة، كما قال تعالى: {فإن أرضعن لكم فآتوهن أجورهن}، وقال: {وعلى المولود له رزقهن وكسوتهن بالمعروف} [البقرة: 233]. والسنة وإجماع الأمة دلّا على جوازها، وإنما تكون مُخالِفة للقياس لو عارضها قياس نص آخر، وليس في سائر النصوص وأقيستها ما يناقض هذه».", "mawaqif": [{"taliq": 6665, "mi": 0, "aya": 6, "alam": "ابن تيمية", "fil": "قال", "kind": "قول", "ref": "6/ 330", "qawl": "", "nass": "هذه الآية توجب رزق المرتضع على أبيه؛ لقوله: {وإن كن أولات حمل فأنفقوا عليهن حتى يضعن حملهن فإن أرضعن لكم فآتوهن أجورهن}، فأوجب نفقته حملا ورضيعا بواسطة الإنفاق على الحامل والمرضع؛ فإنه لا يمكن رزقه بدون رزق حامله ومرضعه", "qawaid": [], "tabi": ""}]}], "8": [{"id": 6666, "kinds": "غيره", "text": "قال ابنُ عطية (8/ 335 بتصرف): «قوله تعالى: {فحاسبناها} قال بعض المتأولين: الآية في الآخرة، أي: ثَمَّ هو الحساب والتعذيب والذوق وخسار العاقبة. وقال آخرون: ذلك في الدنيا، ومعنى: {فَحاسَبْناها حِسابًا شَدِيدًا} أي: لم نغتفر لها زَلة بل أُخِذتْ بالدقائق من الذنوب، وقوله تعالى: {أعد الله لهم عذابًا شديدًا} يظهر منه أنه بيان لوجه خُسران عاقبتهم، فيتأيّد بذلك أن تكون المحاسبة والتعذيب والذوق في الدنيا».", "mawaqif": [{"taliq": 6666, "mi": 0, "aya": 8, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 335 بتصرف", "qawl": "", "nass": "قوله تعالى: {فحاسبناها} قال بعض المتأولين: الآية في الآخرة، أي: ثم هو الحساب والتعذيب والذوق وخسار العاقبة. وقال آخرون: ذلك في الدنيا، ومعنى: {فحاسبناها حسابا شديدا} أي: لم نغتفر لها زلة بل أخذت بالدقائق من الذنوب، وقوله تعالى: {أعد الله لهم عذابا شديدا} يظهر منه أنه بيان لوجه خسران عاقبتهم، فيتأيد بذلك أن تكون المحاسبة والتعذيب والذوق في الدنيا", "qawaid": [], "tabi": ""}]}], "12": [{"id": 6668, "kinds": "تعليق،نقل", "text": "علّق ابن كثير في البداية والنهاية 1/ 43 على هذا الأثر بقوله: «وهو محمول إن صحّ نقله عنه على أنّ ابن عباس? أخذه عن الإسرائيليات».", "mawaqif": [{"taliq": 6668, "mi": 0, "aya": 12, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "", "qawl": "", "nass": "وهو محمول إن صح نقله عنه على أن ابن عباس? أخذه عن الإسرائيليات", "qawaid": [], "tabi": ""}]}, {"id": 6669, "kinds": "توجيه،بيان،نقل", "text": "قال ابن عطية (8/ 336 - 337): «لا خلاف بين العلماء أنّ السموات سبع؛ لأن الله تعالى قال: {سبع سموات طباقًا} [الملك: 3]، وقد فسّر رسول الله صلى الله عليه وسلم أمرهن في حديث الإسراء، وقال صلى الله عليه وسلم لسعد رضي الله عنهما: «حكَمتَ بحكم المَلك من فوق سبع أرقعة». ونطقت بذلك الشريعة في غير ما موضع. وأما» الأرض «فالجمهور على أنها سبع أرضين، وهو ظاهر هذه الآية، وأن المماثلة إنما هي في العدد، ويُستدل بقول رسول الله صلى الله عليه وسلم: «مَن غصب شبرًا من أرض طُوّقه من سبع أرضين». إلى غير هذا مما وردت به روايات، ورُوي عن قوم من العلماء أنهم قالوا: الأرض واحدة، وهي مماثلة لكل سماء بانفرادها في ارتفاع جِرمها، وفي أن فيها عالمًا يعبُد كما في كل سماء عالم يعبُد».\nوقال ابنُ كثير (14/ 44): «ومن حمل ذلك على سبعة أقاليم فقد أبعد النّجعة، وأغرق في النزع، وخالف القرآن والحديث بلا مستند».", "mawaqif": [{"taliq": 6669, "mi": 0, "aya": 12, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 336 - 337", "qawl": "", "nass": "لا خلاف بين العلماء أن السموات سبع؛ لأن الله تعالى قال: {سبع سموات طباقا} [الملك: 3]، وقد فسر رسول الله صلى الله عليه وسلم أمرهن في حديث الإسراء، وقال صلى الله عليه وسلم لسعد رضي الله عنهما: «حكمت بحكم الملك من فوق سبع أرقعة", "qawaid": [], "tabi": ""}, {"taliq": 6669, "mi": 0, "aya": 12, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "14/ 44", "qawl": "", "nass": "ومن حمل ذلك على سبعة أقاليم فقد أبعد النجعة، وأغرق في النزع، وخالف القرآن والحديث بلا مستند", "qawaid": [], "tabi": ""}]}]}, "athar": {"77346": {"num": 77346, "aya": 4, "qail": "أبي بن كعب", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن أُبيّ بن كعب -من طريق عمرو بن سالم- قال: لَمّا نزلت عِدّة المُتوفّى والمُطلّقة قلتُ: يا رسول الله، بقي نساءٌ؛ الصغيرة، والكبيرة، والحامل. فنَزلت: {واللّائِي يَئِسْنَ مِنَ المَحِيضِ} الآية."}, "77347": {"num": 77347, "aya": 4, "qail": "أبي بن كعب", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن أُبيّ بن كعب -من طريق عمرو بن سالم-: أنّ ناسًا مِن أهل المدينة لَمّا أُنزِلَت هذه الآية التي في البقرة في عِدّة النّساء قالوا: لقد بَقي من عِدّة النّساء عِدَدٌ لم تُذكَر في القرآن؛ الصغار، والكبار اللائي قد انقطع عنهن الحَيْض، وذوات الحمْل. فأنزل الله التي في سورة النساء القُصْرى: {واللّائِي يَئِسْنَ مِنَ المَحِيضِ} الآية."}, "77350": {"num": 77350, "aya": 4, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر-من طريق بن أبي نجيح- {إنِ ارْتَبْتُمْ} قال: إن لم تعلموا أتَحيض أم لا؟ فالتي قَعدت عن المَحِيض والتي لم تَحض بعد {فعدتهن ثلاثة أشهر}."}, "77351": {"num": 77351, "aya": 4, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر ="}, "77357": {"num": 77357, "aya": 4, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة، {واللّائِي يَئِسْنَ مِنَ المَحِيضِ مِن نِسائِكُمْ إنِ ارْتَبْتُمْ فَعِدَّتُهُنَّ ثَلاثَةُ أشْهُرٍ} قال: هنّ اللاتي قَعدن من المَحِيض، {واللّائِي لَمْ يَحِضْنَ} فهنّ الأبكار الجواري اللاتي لم يَبلغن المَحِيض."}, "77359": {"num": 77359, "aya": 4, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- في قوله: {واللّائِي يَئِسْنَ مِنَ المَحِيضِ مِن نِسائِكُمْ} يقول: التي قد ارتفع حَيْضها، فعِدّتها ثلاثة أشهر، {واللّائِي لَمْ يَحِضْنَ} قال: الجواري."}, "77362": {"num": 77362, "aya": 4, "qail": "أبى معيد", "tabaqa": "", "bab": "تفسير الآية", "text": "عن أبى مُعَيد، قال: سُئِل سليمان عن المُرتابة. قال: هي المرأة التي قد قَعدت من الولد؛ تُطلَّق، فتَحيض حَيْضة، فيأتي إبّان حَيْضتها الثانية فلا تَحيض. قال: تعتدّ حين ترتاب ثلاثة أشهر مُستقبلة. قال: فإنْ حاضتْ حَيْضتين، ثم جاء إبّان الثالثة فلم تَحض؛ اعتدّت حين تَرتاب ثلاثة أشهر مُستقبلة، ولم يُعتدّ بما مضى."}, "77364": {"num": 77364, "aya": 4, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {واللّائِي يَئِسْنَ مِنَ المَحِيضِ مِن نِسائِكُمْ إنِ ارْتَبْتُمْ فَعِدَّتُهُنَّ ثَلاثَةُ أشْهُرٍ} قال: إن ارْتَبْتَ أنها لا تَحيض وقد ارتفعتْ حَيْضتها، أو ارتاب الرجال، أو قالت هي: ترَكتني الحَيْضة، {فَعِدَّتُهُنَّ ثَلاثَةُ أشْهُر} إن ارتاب فخاف أن تكون الحَيْضة قد انقطعتْ، فلو كان الحمْل انتظَر الحمْل حتى تنقضي تسعة أشهر، فخاف وارتاب هو وهي أن تكون الحَيْضة قد انقطعتْ، فلا ينبغي لِمُسلمة أن تُحبس، فاعتدّتْ ثلاثة أشهر، وجعل الله -جلّ ثناؤه- أيضًا للتي لم تَحض الصغيرة ثلاثة أشهر."}, "77367": {"num": 77367, "aya": 4, "qail": "أبي الشعثاء جابر بن زيد", "tabaqa": "تابعي", "bab": "أحكام متعلقة بالآية", "text": "عَن أبي الشّعثاء جابر بن زيد -من طريق عمرو بن دينار- في المرأة الشابّة تُطلّق فيرتفع حَيْضها، فلا تدري ما رفعها. قال: تعتدّ بالحَيْض. ="}, "77383": {"num": 77383, "aya": 4, "qail": "علي", "tabaqa": "صحابي", "bab": "تفسير الآية، والنسخ فيها", "text": "وقال علي: أربعة أشهر وعشرًا. قال زيد: أرأيتَ إن كانتْ آيِسًا؟ قال علي: فآخِر الأَجَلَيْن. ="}, "77385": {"num": 77385, "aya": 4, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "تفسير الآية، والنسخ فيها", "text": "عن عبد الله بن مسعود -من طريق علقمة- أنه بلَغه أنّ عليًّا يقول: تعتدّ آخر الأَجَلَيْن. فقال: مَن شاء لاعنتُه أنّ الآية التي نَزَلَتْ في سورة النّساء القُصْرى نزلت بعد سورة البقرة: {وأُولاتُ الأَحْمالِ أجَلُهُنَّ أنْ يَضَعْنَ حَمْلَهُنَّ} بكذا وكذا شهرًا، فكلّ مُطلّقة أو مُتوفّى عنها زوجها فأجلُها أن تضع حمْلَها."}, "77386": {"num": 77386, "aya": 4, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "تفسير الآية، والنسخ فيها", "text": "عن عبد الله بن مسعود -من طريق مسروق- قال: مَن شاء حالفتُه أنّ سورة النّساء الصُّغرى أُنزِلت بعد الأربعة أشهر وعشرًا: {وأُولاتُ الأَحْمالِ أجَلُهُنَّ أنْ يَضَعْنَ حَمْلَهُنَّ}."}, "77387": {"num": 77387, "aya": 4, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "تفسير الآية، والنسخ فيها", "text": "عن عبد الله بن مسعود -من طريق مسروق- قال: مَن شاء لاعنتُه أنّ الآية التي في سورة النسّاء القُصْرى: {وأُولاتُ الأَحْمالِ أجَلُهُنَّ أنْ يَضَعْنَ حَمْلَهُنَّ} نَسَختْ ما في البقرة."}, "77388": {"num": 77388, "aya": 4, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "تفسير الآية، والنسخ فيها", "text": "عن عبد الله بن مسعود، قال: نَسَختْ سورةُ النّساء القُصْرى كلَّ عِدَّة: {وأُولاتُ الأَحْمالِ أجَلُهُنَّ أنْ يَضَعْنَ حَمْلَهُنَّ} أجل كلِّ حاملٍ مُطلَّقة، أو مُتوفّى عنها زوجُها أن تَضع حمْلها."}, "77389": {"num": 77389, "aya": 4, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "تفسير الآية، والنسخ فيها", "text": "عن عبد الله بن مسعود -من طريق مالك بن عامر- قال: أتجعَلون عليها التّغليظ ولا تَجعلون لها الرّخصة؟! أُنزلت سورة النّساء القُصْرى بعد الطُّولى: {وأُولاتُ الأَحْمالِ أجَلُهُنَّ أنْ يَضَعْنَ حَمْلَهُنَّ} إذا وضَعتْ فقد انقَضت العِدّة."}, "77399": {"num": 77399, "aya": 4, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية، والنسخ فيها", "text": "عن قتادة بن دعامة، قال: إذا أسقَطت المرأة فقد استَبان حمْلها، وقد مات عنها زوجها أو طَلَّقها فقد انقَضتْ عِدّتها، وإذا أسقَطت أُمُّ الولد فإذا تَبيّن حمْلُها فلا رِقَّ عليها."}, "77400": {"num": 77400, "aya": 4, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية، والنسخ فيها", "text": "عن قتادة بن دعامة: {وأُولاتُ الأَحْمالِ أجَلُهُنَّ أنْ يَضَعْنَ حَمْلَهُنَّ} فإذا نَفضَت الرَّحِم ما فيها فقد انقَضتْ عِدّتها. قال: وذُكر لنا: أنّ سُبَيعة بنت الحارث الأَسلميّة وضَعت بعد وفاة زوجها بخمس عشرة ليلة، فأمرها نبيُّ الله صلى الله عليه وسلم أن تزوّج، قال: وكان عمر يقول: لو وضَعتْ ما في بطنها، وهو موضوعٌ على سريره مِن قبل أن يُقبر لَحلَّتْ."}, "77401": {"num": 77401, "aya": 4, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية، والنسخ فيها", "text": "عن قتادة بن دعامة -من طريق سعيد- {وأُولاتُ الأَحْمالِ أجَلُهُنَّ أنْ يَضَعْنَ حَمْلَهُنَّ}: فإذا وضَعتْ ما في رَحِمها فقد انقَضتْ عِدّتُها، ليس المَحِيض مِن أمرها في شيء إذا كانت حاملًا."}, "77402": {"num": 77402, "aya": 4, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "تفسير الآية، والنسخ فيها", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- قوله: {وأُولاتُ الأَحْمالِ أجَلُهُنَّ أنْ يَضَعْنَ حَمْلَهُنَّ}، قال: للمرأة الحُبلى التي يُطلّقها زوجها وهي حامل، فعِدّتها أن تضع حمْلها."}, "77411": {"num": 77411, "aya": 4, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار في أحكام الآية", "text": "عن عبد الله بن عباس -من طريق عبيد الله- أنه سُئل عن رجل اشترى جارية وهي حامل؛ أيطؤها؟ قال: لا. وقرأ: {وأُولاتُ الأَحْمالِ أجَلُهُنَّ أنْ يَضَعْنَ حَمْلَهُنَّ}."}, "77414": {"num": 77414, "aya": 6, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية- في قوله: {مِن وُجْدِكُمْ}، قال: مِن سَعَتِكم."}, "77417": {"num": 77417, "aya": 6, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- في قوله: {أسْكِنُوهُنَّ مِن حَيْثُ سَكَنْتُمْ} قال: المرأة يُطلّقها، فعليه أن يُسكنها، ويُنفق عليها، {مِن وُجْدِكُمْ} قال: مِن مِلككم؛ من مَقدرتكم."}, "77422": {"num": 77422, "aya": 6, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- {ولا تُضارُّوهُنَّ لِتُضَيِّقُوا عَلَيْهِنَّ}، قال: لتُضيِّقوا عليهنّ مساكنهنّ حتى يَخرُجنَ."}, "77424": {"num": 77424, "aya": 6, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "تفسير الآية، وأحكامها", "text": "عن إبراهيم النَّخْعي، قال: كان عمر وعبد الله [بن مسعود] يَجعلان للمُطلّقة ثلاثًا: السُّكنى، والنّفقة، والمُتعة. ="}, "77426": {"num": 77426, "aya": 6, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية، وأحكامها", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {وإنْ كُنَّ أُولاتِ حَمْلٍ فَأَنْفِقُوا عَلَيْهِنَّ حَتّى يَضَعْنَ حَمْلَهُنَّ}، قال: فهذه المرأة يُطلِّقها زوجُها وهي حامل، فأمَر الله أن يُسكنها ويُنفق عليها حتى تضع، وإنْ أرضعتْه فحتى تَفطِم، فإنْ أبانَ طلاقها وليس بها حمْل فلها السُّكنى حتى تَنقضي عِدّتها، ولا نفقة لها."}, "77428": {"num": 77428, "aya": 6, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "تفسير الآية، وأحكامها", "text": "عن إبراهيم النَّخْعي -من طريق الأعمش- قال: للمُطلّقة ثلاثًا: السُّكنى، والنّفقة."}, "77430": {"num": 77430, "aya": 6, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "تفسير الآية، وأحكامها", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- في قوله: {وإنْ كُنَّ أُولاتِ حَمْلٍ فَأَنْفِقُوا عَلَيْهِنَّ حَتّى يَضَعْنَ حَمْلَهُنَّ}، قال: يُنفَق على الحُبلى إذا كانت حاملًا حتى تضع حمْلها."}, "77433": {"num": 77433, "aya": 6, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "تفسير الآية، وأحكامها", "text": "عن إبراهيم النَّخْعي -من طريق منصور- في الصّبي: إذا قام على ثمن، فأُمّه أحقّ أن تُرضعه، فإن لم يجد له مَن يُرضعه أُجبِرت الأُمّ على الرّضاع."}, "77436": {"num": 77436, "aya": 6, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "تفسير الآية، وأحكامها", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- {فَإنْ أرْضَعْنَ لَكُمْ فَآتُوهُنَّ أُجُورَهُنَّ}، قال: ما تَراضَوا عليه؛ على المُوسِع قدره، وعلى المُقتر قدره}."}, "77439": {"num": 77439, "aya": 6, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- في قوله: {وأْتَمِرُوا بَيْنَكُمْ بِمَعْرُوفٍ}، قال: اصنعوا المعروف في ما بينكم."}, "77444": {"num": 77444, "aya": 6, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النَّخْعي ="}, "77447": {"num": 77447, "aya": 6, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- في قوله: {وإنْ تَعاسَرْتُمْ فَسَتُرْضِعُ لَهُ أُخْرى}، قال: إنْ أبَت الأُمُّ أن تُرضِع ولدها -إذا طلّقها زوجُها؛ أبوه- التمَس له مُرضِعة أخرى، الأُمّ أحقّ إذا رَضيتْ مِن أجر الرّضاع بما يَرضى به غيرُها، فلا ينبغي له أن يُنتزَع منها."}, "77452": {"num": 77452, "aya": 6, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- {لِيُنْفِقْ ذُو سَعَةٍ مِن سَعَتِهِ} قال: من سَعة مَوجدته، {ومَن قُدِرَ عَلَيْهِ رِزْقُهُ} قال: مَن قُتِّر عليه رِزقه."}, "77468": {"num": 77468, "aya": 8, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- في قوله: {وكَأَيِّنْ مِن قَرْيَةٍ عَتَتْ عَنْ أمْرِ رَبِّها ورُسُلِهِ}، قال: غيّرتْ وعَصتْ."}, "77471": {"num": 77471, "aya": 8, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- قوله: {وكَأَيِّنْ مِن قَرْيَةٍ عَتَتْ}، قال: العُتوّ ههنا: الكفر والمعصية؛ عَتَوا: كفروا. ترَكت أمر ربها: عَتتْ عن أمره ولم تَقبله."}, "77473": {"num": 77473, "aya": 8, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "قال إسماعيل السُّدِّيّ: {فَحاسَبْناها حِسابًا شَدِيدًا}، يعني: فجازيناها جزاءً شديدًا."}, "77475": {"num": 77475, "aya": 8, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {فَحاسَبْناها حِسابًا شَدِيدًا}، قال: لم نَعفُ عنها، الحساب الشديد الذي ليس فيه من العفو شيء."}, "77483": {"num": 77483, "aya": 10, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- في قوله: {فاتَّقُوا اللَّهَ يا أُولِي الأَلْبابِ}، قال: يا أولي العقول."}, "77487": {"num": 77487, "aya": 10, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {قَدْ أنْزَلَ اللَّهُ إلَيْكُمْ ذِكْرًا}، قال: القرآن رُوح من الله. وقرأ: {وكَذَلِكَ أوْحَيْنا إلَيْكَ رُوحًا مِن أمْرِنا} [الشورى: 52] إلى آخر الآية. وقرأ: {قَدْ أنْزَلَ اللَّهُ إلَيْكُمْ ذِكْرًارَسُولًا} قال: القرآن. وقرأ: {إنَّ الَّذِينَ كَفَرُوا بِالذِّكْرِ لَمّا جاءَهُمْ} [فصلت: 41]، قال: بالقرآن. وقرأ: {إنّا نَحْنُ نَزَّلْنا الذِّكْرَ} [الحجر: 9]، قال: القرآن. قال: وهو الذِّكر، وهو الرّوح."}, "77155": {"num": 77155, "aya": 1, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "قراءات", "text": "عن عبد الله بن عمر: أنّ رسول الله صلى الله عليه وسلم قرأ: (فَطَلِّقُوهُنَّ فِي قُبُلِ عِدَّتِهِنَّ)."}, "77156": {"num": 77156, "aya": 1, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "قراءات", "text": "عن عبد الله بن عباس -من طريق عمرو بن دينار- أنه كان يقرأ: (فَطَلِّقُوهُنَّ لِقُبُلِ عِدَّتِهِنَّ)."}, "77157": {"num": 77157, "aya": 1, "qail": "مجاهد", "tabaqa": "تابعي", "bab": "قراءات", "text": "عن مجاهد، قال: كان ابن عباس يقرأ هذا الحرف: (يَآ أيُّها النَّبِيُّ إذا طَلَّقْتُمُ النِّساءَ فَطَلِّقُوهُنَّ فِي قُبُلِ عِدَّتِهِنَّ)."}, "77158": {"num": 77158, "aya": 1, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "قراءات", "text": "عن عبد الله بن عمر -من طريق عبد الرحمن بن يزيد- أنه قرأ: (فَطَلِّقُوهُنَّ لِقُبُلِ عِدَّتِهِنَّ)."}, "77159": {"num": 77159, "aya": 1, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "قراءات", "text": "عن مجاهد بن جبر -من طريق ابن جُرَيْج- أنه كان يقرأ: (فَطَلِّقُوهُنَّ لِقُبُلِ عِدَّتِهِنَّ)."}, "77160": {"num": 77160, "aya": 1, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "قراءات", "text": "عن مجاهد بن جبر -من طريق عبد الله بن كثير- أنه قرأ: (فَطَلِّقُوهُنَّ فِي قُبُلِ عِدَّتِهِنَّ)."}, "77161": {"num": 77161, "aya": 1, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس، قال: طلّق عبدُ يزيد أبو رُكانة أُمَّ رُكانة، ثم نكح امرأة من مُزْيَنة، فجاءت إلى رسول الله صلى الله عليه وسلم، فقالت: يا رسول الله، ما يُغني عنِّي إلا ما تُغني عنِّي هذه الشَّعرة. لِشعرةٍ أخذَتْها من رأسها، فأخَذَتْ رسول الله صلى الله عليه وسلم حَمِيَّةٌ عند ذلك، فدعا رسولُ الله صلى الله عليه وسلم رُكانة وإخوته، ثم قال لجلسائه: «أترون كذا مِن كذا؟». فقال رسول الله صلى الله عليه وسلم لعبد يزيد: «طلِّقها». ففعل، فقال لأبي رُكانة: «ارْتَجِعها». فقال: يا رسول الله، إني طلّقتها. قال: «قد علمتُ ذلك، فارتَجِعها». فنزلت: {يا أيُّها النَّبِيُّ إذا طَلَّقْتُمُ النِّساءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ}."}, "77163": {"num": 77163, "aya": 1, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عمر -من طريق أبي الزبير- أنه طلّق امرأته وهي حائض على عهد النبيِّ صلى الله عليه وسلم، فانطلَق عمر، فذكر ذلك له، فقال: «مُره فليُراجِعها، ثم يُمسكها حتى تَطهر، ثم يُطَلّقها إن بدا له». فأنزل الله عند ذلك: (يَآ أيُّها النَّبِيُّ إذا طَلَّقْتُمُ النِّسَآءَ فَطَلِّقُوهُنَّ فِي قُبُلِ عِدَّتِهِنَّ). قال أبو الزّبير: هكذا سمعتُ ابنَ عمر يقرؤها."}, "77164": {"num": 77164, "aya": 1, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "قال إسماعيل السُّدِّيّ: نَزَلَت في عبد الله بن عمر، وذلك أنه طلّق امرأته حائضًا، فأمره رسول الله صلى الله عليه وسلم أن يُراجِعها ويُمسكها حتى تَطهر، ثم تَحيض حَيْضة أخرى، فإذا طَهرتْ طلّقها؛ إن شاء قبل أن يُجامِعها، فإنها العِدّة التي أمر الله بها."}, "77167": {"num": 77167, "aya": 1, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عمر، عن النبيِّ صلى الله عليه وسلم: {فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ}، قال: «طاهِرًا مِن غير جِماع»."}, "77169": {"num": 77169, "aya": 1, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عمر -من طريق نافع- أنه طلق امرأته وهي حائض على عهد رسول الله صلى الله عليه وسلم، فسأل عمرُ بن الخطاب رسول الله صلى الله عليه وسلم عن ذلك، فقال رسول الله صلى الله عليه وسلم: «مُره فليراجعها، ثم ليمسكها حتى تطهر، ثم تحيض، ثم تطهر، ثم إن شاء أمسك بعد، وإن شاء طلَّق قبل أن يمسّ، فتلك العِدَّة التي أمر الله أن تُطلَّق لها النساء»."}, "77173": {"num": 77173, "aya": 1, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق مجاهد- في هذه الآية: {يا أيُّها النَّبِيُّ إذا طَلَّقْتُمُ النِّساءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ}، قال: في قُبل عِدّتهنّ."}, "77174": {"num": 77174, "aya": 1, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عكرمة- في قوله: {فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ}، قال: طاهِرًا من غير جماع."}, "77175": {"num": 77175, "aya": 1, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق علي- {فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ}، قال: لا يُطلّقها وهي حائض، ولا في طُهرٍ قد جامعها فيه، ولكن يَتركها، حتى إذا حاضتْ وطهُرتْ طلّقها تطليقة، فإن كانت تَحيض فعِدّتها ثلاث حِيَض، وإن كانت لا تَحيض فعِدّتها ثلاثة أشهر، وإن كانتْ حاملًا فعِدّتها أن تَضع حَمْلها، وإذا أراد مُراجعتها قبل أن تنقضي عِدّتها أشهد على ذلك رجلين، كما قال الله: {وأَشْهِدُوا ذَوَيْ عَدْلٍ مِنكُمْ} عند الطَّلاق وعند المُراجعة، فإن راجَعها فهي عنده على تطليقتين، وإن لم يُراجِعها فإذا انقَضتْ عِدّتها فقد بانتْ منه واحدة، وهي أملكُ بنفسها، ثم تتزوّج مَن شاءت، هو أو غيره."}, "77176": {"num": 77176, "aya": 1, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق الضَّحّاك- أنّ نافع بن الأزرق سأله، فقال: أخبِرني عن قول الله عز وجل: {يا أيُّها النَّبِيُّ إذا طَلَّقْتُمُ النِّساءَ}، هل كان الطَّلاق في الجاهلية؟ قال: نعم، طلاقًا بائنًا ثلاثًا، أما سمعتَ قول أعشى بني قيس بن ثَعلبة حين أخذه أخْتانُهُ عَنَزَةُ فقالوا له: إنك قد أضررتَ بصاحبتنا، وإنّا نقسم بالله أن لا نضع العصا عنك أو تُطلّقها، فلمّا رأى الجِدّ منهم وأنهم فاعلون به شرًّا قال: يا جارَتا بِينِي فَإنَّكِ طالِقَه … كذاكَ أُمُورُ الناس غادٍ وطارِقَهْ فقالوا: واللهِ، لتَبيننّ لها الطَّلاق أو لا نضع العصا عنك. فقال: فَبِينِي حَصانَ الفَرْجِ غَيْرَ ذَمِيمَةٍ … وما مُوقَةٌ مِنّا كَما أنتِ وامِقَهْ فقالوا: واللهِ، لتَبيننّ الطَّلاق أو لا نضع العصا عنك. فقال: وبِينِي فَإنَّ البَيْنَ خَيْرٌ مِنَ العَصا … وإن لا تَزالِي فَوْقَ رَأْسِكِ بارِقَهْ فأبانها بثلاث طلقات."}, "77177": {"num": 77177, "aya": 1, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عمر، {فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ}، قال: في الطُّهْر في غير جِماع."}, "77178": {"num": 77178, "aya": 1, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق منصور- {فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ}، قال: طُهرهن. وفي لفظ: قال: طاهرًا في غير جماع."}, "77181": {"num": 77181, "aya": 1, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "والحسن البصري -من طريق يونس- أنهما قالا في الطَّلاق لِعِدّة: أن يُطلّق امرأته تطليقة وهي طاهر مِن غير جماع، ثم يَدَعها إن لم تكن له فيها حاجة حتى تَنقضي العِدّة، فإن كان له فيها حاجة راجَعها في العِدّة، فعل."}, "77185": {"num": 77185, "aya": 1, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق إسماعيل بن مسلم- في قوله: {فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ}، قال: طاهرًا مِن غير حَيضٍ، أو حاملًا قد استبان حمْلها."}, "77186": {"num": 77186, "aya": 1, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {يا أيُّها النَّبِيُّ إذا طَلَّقْتُمُ النِّساءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ}: والعِدّة: أن يُطلّقها طاهرًا مِن غير جماع تطليقة واحدة."}, "77187": {"num": 77187, "aya": 1, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة، {فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ}، قال: العِدّة: أن يطلّقها طاهرًا من غير جماع. فأما الرجل يخالط امرأته، حتى إذا أقلَع عنها طلّقها عند ذلك، فلا يدري أحاملًا هي أم غير حامل؛ فإنّ ذلك لا يَصلُح."}, "77188": {"num": 77188, "aya": 1, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق معمر- في قوله: {فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ}، قال: إذا طَهَرتْ من الحيض في غير جماع. قلت: كيف؟ قال: إذا طَهَرتْ فطلِّقها مِن قبل أن تَمسّها، فإن بدا لك أن تُطلّقها أخرى ترَكتَها حتى تَحيض حَيْضة أخرى، ثم طلِّقها إذا طَهَرت الثانية، فإذا أردتَ طلاقها الثالثة أمهَلتها حتى تَحيض، فإذا طَهَرتْ طلِّقها الثالثة، ثم تعتدّ حَيْضة واحدة، ثم تُنكح إن شاءتْ."}, "77189": {"num": 77189, "aya": 1, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- في قوله: {إذا طَلَّقْتُمُ النِّساءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ}، قال: طاهرًا في غير جماع، فإن كانت لا تَحيض فعند غُرّة كلّ هلال."}, "77199": {"num": 77199, "aya": 1, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "من أحكام الآية", "text": "عن عبد الله بن عباس -من طريق عكرمة- قال: الطَّلاق على أربعة منازل: منزلان حلال، ومنزلان حرام؛ فأما الحرام فأن يُطلّقها حين يُجامعها، ولا يدري أشتمل الرَّحِم على شيء أو لا؟ وأن يُطلّقها وهي حائض، وأما الحلال فأن يُطلّقها لأقرائها طاهرًا عن غير جماع، وأن يُطلّقها مُستبينًا حمْلها."}, "77200": {"num": 77200, "aya": 1, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "من أحكام الآية", "text": "عن عبد الله بن عباس -من طريق مجاهد- أنه سُئل عن رجل طلّق امرأته مائة. قال: عصيتَ ربك، مَن يتق الله يجعل له مخرجًا. ثم تلا: (يَآ أيُّها النَّبِيُّ إذا طَلَّقْتُمُ النِّساءَ فَطَلِّقُوهُنَّ فِي قُبُلِ عِدَّتِهِنَّ)."}, "77201": {"num": 77201, "aya": 1, "qail": "مجاهد", "tabaqa": "تابعي", "bab": "من أحكام الآية", "text": "عن مجاهد، قال: سأل ابنَ عباس يومًا رجلٌ، فقال: يا أبا عباس، إني طلّقتُ امرأتي ثلاثًا. فقال ابن عباس: عصيتَ ربك، وحرُمتْ عليك امرأتُك، ولم تتق الله ليجعل لك مخرجًا، يُطلّق أحدكم ثم يقول: يا أبا عباس! قال الله: (يَآ أيُّها النَّبِيُّ إذا طَلَّقْتُمُ النِّسَآءَ فَطَلِّقُوهُنَّ فِي قُبُلِ عِدَّتِهِنَّ)."}, "77202": {"num": 77202, "aya": 1, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "من أحكام الآية", "text": "عن الحسن البصري ="}, "77205": {"num": 77205, "aya": 1, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- قوله: {وأَحْصُوا العِدّة}، قال: احفظوا العِدّة."}, "77211": {"num": 77211, "aya": 1, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "تفسير الآية، وأحكامها", "text": "عن عبد الله بن عمر، قال: المُطلّقة والمُتوفّى عنها زوجها يَخرجان بالنهار، ولا يَبيتان ليلةً تامةً عن بيوتهما."}, "77218": {"num": 77218, "aya": 1, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية، وأحكامها", "text": "والحسن البصري -من طريق أيوب- يقولان: المُطلَّقة ثلاثًا والمُتوفّى عنها زوجها لا سُكنى لها ولا نفقة."}, "77220": {"num": 77220, "aya": 1, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {لا تُخْرِجُوهُنَّ مِن بُيُوتِهِنَّ ولا يَخْرُجْنَ}: وذلك إذا طلَّقها واحدة أو ثنتين لها، ما لم يُطلّقها ثلاثًا."}, "77222": {"num": 77222, "aya": 1, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- قوله: {واتَّقُوا اللَّهَ رَبَّكُمْ لا تُخْرِجُوهُنَّ مِن بُيُوتِهِنَّ}: حتى تَنقضي عِدّتُهُنَّ."}, "77224": {"num": 77224, "aya": 1, "qail": "قتادة", "tabaqa": "تابعي", "bab": "قراءات", "text": "عن قتادة، قال: في حرف ابن مسعود: (إلَّآ أن يَّفْحُشْنَ)."}, "77226": {"num": 77226, "aya": 1, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق محمد بن إبراهيم- في قوله: {ولا يَخْرُجْنَ إلّا أنْ يَأْتِينَ بِفاحِشَةٍ مُبَيِّنَةٍ}، قال: الفاحشة المُبيّنة أن تَبْذُوَ المرأةُ على أهل الرجل، فإذا بذَتْ عليهم بلسانها فقد حلَّ لهم إخراجها."}, "77227": {"num": 77227, "aya": 1, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق محمد بن سعد- {إلّا أنْ يَأْتِينَ بِفاحِشَةٍ مُبَيِّنَةٍ}: والفاحشة: هي المعصية."}, "77229": {"num": 77229, "aya": 1, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، في قوله: {ولا يَخْرُجْنَ إلّا أنْ يَأْتِينَ بِفاحِشَةٍ مُبَيِّنَةٍ}، قال: الزِّنا."}, "77230": {"num": 77230, "aya": 1, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق قتادة- ="}, "77232": {"num": 77232, "aya": 1, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عمر -من طريق نافع- في قوله: {ولا يَخْرُجْنَ إلّا أنْ يَأْتِينَ بِفاحِشَةٍ مُبَيِّنَةٍ}، قال: خروجها قبل انقضاء العِدّة من بيتها الفاحشة المُبيّنة."}, "77234": {"num": 77234, "aya": 1, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {ولا يَخْرُجْنَ إلّا أنْ يَأْتِينَ بِفاحِشَةٍ مُبَيِّنَةٍ}، قال: إلا أن يَزْنِينَ."}, "77241": {"num": 77241, "aya": 1, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق معمر- {بِفاحِشَةٍ مُبَيِّنَةٍ}، قال: هو النُّشُوز."}, "77242": {"num": 77242, "aya": 1, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- {إلّا أنْ يَأْتِينَ بِفاحِشَةٍ مُبَيِّنَةٍ}: إلا أن يُطلّقها على نشوز، فلها أن تُحوّل من بيت زوجها."}, "77244": {"num": 77244, "aya": 1, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- في قوله: {ولا يَخْرُجْنَ إلّا أنْ يَأْتِينَ بِفاحِشَةٍ مُبَيِّنَةٍ}، قال: خروجها من بيتها فاحشة. قال بعضهم: خروجها إذا أتتْ بفاحشة أن تُخرَج فيقام عليها الحدّ."}, "77261": {"num": 77261, "aya": 1, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري، {لَعَلَّ اللَّهَ يُحْدِثُ بَعْدَ ذَلِكَ أمْرًا}، قال: المُراجعة."}, "77264": {"num": 77264, "aya": 1, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "قال الحسن البصري -من طريق سعيد-: هذا في الواحدة والثّنتين، وما يُحدِث الله بعد الثلاث؟!."}, "77265": {"num": 77265, "aya": 1, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق معمر- في قوله: {لَعَلَّ اللَّهَ يُحْدِثُ بَعْدَ ذَلِكَ أمْرًا}، قال: هذا في مُراجعة الرجل امرأته."}, "77266": {"num": 77266, "aya": 1, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- {لا تَدْرِي لَعَلَّ اللَّهَ يُحْدِثُ بَعْدَ ذَلِكَ أمْرًا}، قال: يُراجِعها في بيتها، هذا في الواحدة والثّنتين، هو أبعد مِن الزِّنا."}, "77267": {"num": 77267, "aya": 1, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة، {لا تَدْرِي لَعَلَّ اللَّهَ يُحْدِثُ بَعْدَ ذَلِكَ أمْرًا}، قال: إن بدا له أن يُراجِعها راجَعها في بيتها، هو أبعد مِن قَذَر الأخلاق، وأطوع لله أن تَلزم بيتها."}, "77268": {"num": 77268, "aya": 1, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- {لَعَلَّ اللَّهَ يُحْدِثُ بَعْدَ ذَلِكَ أمْرًا}، قال: الرَّجعة."}}, "n_athar": {"0": 13, "1": 117, "2": 49, "3": 25, "4": 67, "5": 1, "6": 43, "7": 11, "8": 8, "9": 7, "10": 5, "11": 1, "12": 21}, "muh": ["ابن جرير", "ابن عطية", "ابن كثير", "ابن تيمية", "ابن القيم"], "ords": ["الأول", "الثاني", "الثالث", "الرابع", "الخامس", "السادس", "السابع", "الثامن", "التاسع", "العاشر"], "index": "فهرس.html"});